  "measure_id": "CA-2026-P41",
  "restatements": [
    {
      "clause_id": "Prop 41 Sec. 3",
      "text": "States the measure's purpose is to require audits of programs receiving new or higher special taxes and to prohibit exemptions from the state spending limit."
    },
    {
      "clause_id": "Prop 41 Sec. 4 §1",
      "text": "Requires the California State Auditor to prepare a pre-election financial and performance audit for any proposed special tax initiative, detailing potential savings, waste, and goal achievement, with an executive summary printed in the voter guide. The Auditor is reimbursed from the tax revenue if the measure passes."
    },
    {
      "clause_id": "Prop 41 Sec. 4 §2",
      "text": "Requires the State Auditor to conduct ongoing financial and performance audits every four years for programs receiving money from new or higher special taxes enacted after January 1, 2026."
    },
    {
      "clause_id": "Prop 41 Sec. 4 §3",
      "text": "Prohibits any state tax enacted or taking effect after January 1, 2026, from being exempted or excluded from the constitutional Government Spending Limitation, and forbids the state from collecting any tax that attempts such an exemption."
    },
    {
      "clause_id": "Prop 41 Sec. 5",
      "text": "Declares that if this measure receives more votes than a conflicting measure on the same ballot, the conflicting measure is entirely null and void."
    },
    {
      "clause_id": "Prop 41 Sec. 9",
      "text": "Requires the Attorney General to appoint independent counsel to defend the measure if the Governor and Attorney General refuse to do so, and creates a continuous General Fund appropriation to cover the counsel's costs."
    }
  ],
